// q-pointer02.c
#include <stdio.h>

void func(int* a) {
    int x = 1;
    for (int i = 0; i >= 0; i += x) {
        *(a + i) += i;
        if (i >= 4)
            x = -1;
    }
}

int main(void) {
    int arr1[] = {«a=1|2|4|3»,«b=2|3|5|1»,«c=3|1|6|2»,«d=2|4|7|5»,«e=1|5|8|2»};
    func(arr1);
    for (int i = 4; i >= 0; i--) {
        printf("%d ", arr1[i]);
    }
    return 0;
}

